-- Independent Dadyoom teaching supports, not claims about the contents of official books.
-- Idempotent: update only short published placeholders while retaining prior text and add each origin/type once.
DO $dadyoom$
DECLARE
  r RECORD;
  target_id uuid;
  target_content text;
BEGIN
  FOR r IN SELECT * FROM jsonb_to_recordset('[{"n":1,"skill":"الانتماء الوطني في نص مقروء","passage":"يحتاج نص «بلادك يا ولدي» إلى مصدره المدرسي لتحديد المتحدث والشواهد. في فقرة مستقلة من ضاديوم قال أب لابنه: «احفظ نظافة المكان الذي تتعلم فيه، وشارك بجهدك في خدمته». لا تنسب الجملة إلى النص الأصلي. تفهم قيمة الانتماء من السلوك لا الشعارات وحدها.","prompt":"ما السلوك الذي يبرز الانتماء في المثال؟","correct":"خدمة المكان والمحافظة على نظافته","w1":"ترك النفايات","w2":"تجاهل المدرسة","w3":"رفض المشاركة","practice":"استخرج قيمة وطنية من النص الأصلي بشاهد موثق، ثم اكتب مثالًا جديدًا يترجمها إلى فعل."},{"n":2,"skill":"رفع ونصب وجزم المضارع","passage":"«يكتبُ المتدربُ التقريرَ» فعل مضارع مرفوع، و«لن يهملَ القياسَ» منصوب بـ«لن»، و«لم يهملْ القياسَ» مجزوم بـ«لم». ضبط الآخر يتبع الأداة ونوع الفعل، لا مجرد زمن حدوثه.","prompt":"ما إعراب «يهملْ» بعد «لم»؟","correct":"مضارع مجزوم","w1":"مضارع مرفوع","w2":"ماض مبني","w3":"اسم فاعل","practice":"اكتب جملة لكل حالة من حالات المضارع الثلاث، ثم بيّن العامل وعلامة الإعراب."},{"n":3,"skill":"استنتاج الموقف لا اختلاق القصة","passage":"نص «السيد المطاع» يتطلب القراءة المباشرة قبل استنتاج الشخصيات أو أحداثه. في مثال مستقل انتخب فريق قائدًا لأنه يستمع للاقتراحات ويتحقق من النتائج. دلّ السلوك على قيادة مبنية على الثقة لا الخوف، وهذا المثال من ضاديوم فقط.","prompt":"لماذا اختار الفريق قائده في المثال؟","correct":"لإنصاته وتحققه من النتائج","w1":"لأنه يمنع الحوار","w2":"لأنه يخفي النتائج","w3":"لأنه لا يراجع عمله","practice":"بعد قراءة النص المقرر، حدد رأي الكاتب أو الراوي بشاهد صحيح وقارنه بسلوك قائد من إنشائك."},{"n":4,"skill":"تمييز الاسم والفعل والحرف والجمع","passage":"في «قرأ المتدربُ تعليماتٍ واضحةً» «قرأ» فعل، و«المتدرب» اسم، والباء في «بالقلم» حرف جر. «عامل» مفرد و«عمال» جمع تكسير، بينما «عاملون» جمع مذكر سالم. يختلف نوع الجمع بحسب بنائه ولا يصح الحكم من المعنى وحده.","prompt":"ما نوع الجمع «عمال»؟","correct":"جمع تكسير","w1":"جمع مذكر سالم","w2":"جمع مؤنث سالم","w3":"مثنى","practice":"صنّف عشر كلمات إلى اسم وفعل وحرف، ثم حوّل خمسة أسماء إلى جموع مناسبة واشرح نوع كل جمع."},{"n":5,"skill":"كتابة نص من عشرة أسطر","passage":"لتنظيم نص من نحو 120 كلمة، ابدأ بفكرة محددة مثل يوم تدريب ناجح، ثم أضف موقفًا وعقبة واستجابة ونتيجة وخاتمة. لا تكرر الجمل لبلوغ العدد؛ فالترابط والإملاء والدقة أهم من حشو الكلمات.","prompt":"ما الذي يقوي ترابط النص المكتوب؟","correct":"تسلسل الأحداث والسبب والنتيجة","w1":"تكرار الجملة نفسها","w2":"إلغاء الفكرة الرئيسة","w3":"الانتقال العشوائي","practice":"اكتب نصًا أصليًا يقارب 120 كلمة في عشرة أسطر عن تجربة تعلم، وراجعه وفق وضوح الفكرة والترابط والسلامة."},{"n":6,"skill":"قيمة العمل من غير اختلاق اقتباس","passage":"العنوان «ما أشبه العمل بالصلاة» لا يتيح نسبة نص ديني أو تفسير للمؤلف دون المصدر الأصلي. في مثال مستقل أتم عامل المهمة بإخلاص واحترام للوقت مع مساعدة زملائه، فظهرت أهمية النية الجادة والإتقان. النص التدريبي غير منقول من كتاب أو حديث.","prompt":"أي سلوك دل على جدية العامل؟","correct":"الإخلاص واحترام الوقت","w1":"إهمال المهمة","w2":"تعطيل الفريق","w3":"الغياب بلا سبب","practice":"استخرج التشبيه أو الفكرة من النص الأصلي بمصدر صحيح، ثم اكتب فقرة تقارن بين صفتين للعمل الجيد."},{"n":7,"skill":"المفرد والجمع والترادف والتضاد","passage":"«مهمة» مفرد و«مهمات» جمع، و«سريع» و«بطيء» لفظان متضادان في وصف الوتيرة، أما «دقيق» و«متقن» فتتقاربان أحيانًا في سياق وصف العمل من غير تطابق تام. تعتمد العلاقات الدلالية على السياق.","prompt":"ما الكلمة المضادة لـ«سريع»؟","correct":"بطيء","w1":"عاجل","w2":"خاطف","w3":"سريع جدًا","practice":"اكتب خمسة أزواج ترادف وخمسة أزواج تضاد في جمل، ثم حوّل خمسة أسماء من مفرد إلى جمع."},{"n":8,"skill":"التحقق من نص الحديث النبوي","passage":"لا نورد متن حديث أو حكمًا عليه دون معرفة النص المدرسي ومصدره والتحقق من تخريجه. تدريب مستقل: يناقش طالبان أهمية الصدق في تسليم مشروع جماعي، ويقترحان كتابة تقرير يذكر ما أُنجز وما لم يُنجز بأمانة. هذا الحوار ليس حديثًا نبويًا.","prompt":"كيف يظهر الصدق في التقرير التدريبي؟","correct":"ذكر ما أُنجز وما لم يُنجز بأمانة","w1":"اختلاق نتائج","w2":"إخفاء الأخطاء","w3":"حذف أسماء المشاركين","practice":"بإشراف المعلم استخرج النص الحديثي المقرر من مصدر موثوق، ثم ميّز المتن من شرحك الشخصي وطبق قيمة صادقة."},{"n":9,"skill":"الاستفهام والنداء والهمزة وفك الإدغام","passage":"«يا فنيُّ، هل تحققت من الجهاز؟» فيها نداء واستفهام. وفي «ردَّ» فعل ماض مضعّف، وعند اتصاله بتاء الفاعل نقول «رددتُ» بفك الإدغام. رسم الهمزة يحتاج معرفة موضعها وحركتها، ولا يحددها وجود استفهام في الجملة.","prompt":"ما صورة «ردَّ» مع تاء الفاعل؟","correct":"رددتُ","w1":"ردُّتُ","w2":"ردتْتُ","w3":"رَدَدتَتُ","practice":"أنشئ حوارًا يتضمن نداء واستفهامًا، وثلاث كلمات بهمزة، وفعلين مضعفين عند اتصال ضمير."},{"n":10,"skill":"مهمة كتابة ثانية من 120 كلمة","passage":"في تدريب كتابي مستقل قارن بين خطتين لإنجاز مهمة، فبيّن الهدف والموارد والخطوات ومخاطر التأخير ثم علل اختيار الخطة الأنسب. احرص على نحو عشرة أسطر و120 كلمة دون ادعاء مطابقة إجابة نموذجية لكتاب غير متاح.","prompt":"أي جزء يبرر اختيار إحدى الخطتين؟","correct":"تحديد المعايير والنتائج المحتملة","w1":"تكرار العنوان","w2":"إهمال الموارد","w3":"حذف النتيجة","practice":"اكتب نصًا حجاجيًا في عشرة أسطر ونحو 120 كلمة، فيه رأي وحجتان واعتراض وجواب وخاتمة."},{"n":11,"skill":"قراءة رسالة إلى الشباب بلا اختلاق","passage":"لا يصح تحديد نص «إلى الشباب» أو قائل عباراته من العنوان وحده. في نص مستقل دعت معلمة الشباب إلى الاستعداد للمستقبل بتعلم مهارات وتقييم أخطائهم، ووضحت أن الطموح يحتاج خطة قابلة للقياس. هذا نص ضاديوم وليس من الكتاب.","prompt":"ما الرابط الذي أوضحته المعلمة بين الطموح والنجاح؟","correct":"التعلم مع خطة وتقييم","w1":"الانتظار بلا عمل","w2":"الاعتماد على الحظ وحده","w3":"إهمال المهارات","practice":"اكتب رسالة من إنشائك للشباب تشمل هدفًا عمليًا وخطوات ومراجعة للتقدم، ثم قارِن فكرة مع النص الموثق."},{"n":12,"skill":"النداء والاستفهام والألف الفارقة","passage":"«يا زملائي، لماذا تأخرتم؟» يجمع نداء واستفهامًا، والغرض يتضح من السياق. وتكتب الألف الفارقة بعد واو الجماعة في «كتبوا» ولا تكتب بعد الواو الأصلية في «يدعو». نفرق بين صوت الواو ووظيفتها الصرفية.","prompt":"أين تظهر الألف الفارقة؟","correct":"كتبوا","w1":"يدعو","w2":"قلم","w3":"كتاب","practice":"اكتب خمس جمل فيها واو جماعة وخمس كلمات فيها واو أصلية، وفسر رسم الألف في كل مثال."}]'::jsonb) AS x(
    n integer,skill text,passage text,prompt text,correct text,w1 text,w2 text,w3 text,practice text
  ) LOOP
    SELECT l.id,l.content INTO STRICT target_id,target_content
    FROM public.lessons l
    JOIN public.units u ON u.id=l.unit_id
    JOIN public.grades g ON g.id=u.grade_id AND g.grade_number=10
    JOIN public.curricula cu ON cu.id=g.curriculum_id AND cu.academic_year='2026-2027' AND cu.id='e15ed6fd-370c-4980-b724-d0c19ec2c029'
    JOIN public.countries c ON c.id=cu.country_id AND c.code='BH'
    WHERE u.title='عرب 502 — التدريب المهني / السنة الأولى' AND u.semester=2 AND l.sort_order=r.n AND l.status='published'
    FOR UPDATE OF l;
    IF char_length(coalesce(target_content,''))<350 THEN
      UPDATE public.lessons SET
        content='ضاديوم — إثراء مستقل أصلي للصف الثامن، الفصل الثاني. لا يمثل النص الوزاري الأصلي ولا يثبت مطابقة العنوان للمصدر.'||E'\n\n'||
          'المهارة: '||r.skill||E'\n\n'||
          'النموذج التعليمي والشرح: '||r.passage||E'\n\n'||
          'أهداف التعلم: يحدد المتعلم شاهدًا صحيحًا ويشرح دلالته، ويميّز بين الفكرة والدليل، ثم ينتج كتابة مناسبة للمهارة.'||E'\n\n'||
          'سؤال الفهم: '||r.prompt||E'\n\n'||
          'التطبيق الكتابي: '||r.practice||E'\n\n'||
          'التمايز: المبتدئ يحصل على كلمات مفتاحية وبداية جملة؛ المتوسط يجيب بدليل مستقل؛ المتقدم يقارن بين صياغتين ويبرر تحسيناته.'||E'\n\n'||
          'مراجعة المعلم: تحقق من صحة الاستدلال والإملاء وعلامات الترقيم والترابط. لا تُمنح درجة جودة تلقائية لمجرد تسليم المهمة.'||E'\n\n'||
          'تنبيه المصدر: راجع العنوان المستورد والكتاب الرسمي قبل وصف هذا التدريب بأنه مطابق للمنهج.'||E'\n\n'||'المدخل السابق المحفوظ: '||coalesce(target_content,''),
        updated_at=now()
      WHERE id=target_id;
    END IF;
    IF EXISTS (SELECT 1 FROM public.lessons WHERE id=target_id AND content LIKE 'ضاديوم — إثراء مستقل أصلي للصف الثامن%') THEN
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'فهم النص الإثرائي','multiple_choice','assessment',r.prompt,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T2_ARAB502_ORIGINAL_20261008','notOfficialBook',true,'ocrReview','pending','options',CASE (r.n % 4) WHEN 0 THEN jsonb_build_array(r.correct,r.w1,r.w2,r.w3) WHEN 1 THEN jsonb_build_array(r.w1,r.correct,r.w2,r.w3) WHEN 2 THEN jsonb_build_array(r.w1,r.w2,r.w3,r.correct) ELSE jsonb_build_array(r.w1,r.w2,r.correct,r.w3) END),
        jsonb_build_object('correct',r.correct),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='multiple_choice' AND content->>'origin'='DADYOOM_BH_TECH_G10_T2_ARAB502_ORIGINAL_20261008');
      INSERT INTO public.lesson_activities (lesson_id,title,activity_type,section,prompt,content,answer,activity_order,points,is_required,is_published)
      SELECT target_id,'كتابة تطبيقية بمراجعة المعلم','writing','practice',r.practice,
        jsonb_build_object('origin','DADYOOM_BH_TECH_G10_T2_ARAB502_ORIGINAL_20261008','notOfficialBook',true,'humanReviewRequired',true,'text',r.practice,'skillQualityAutoVerified',false),
        jsonb_build_object('grading_mode','completion_only_reference','model_answer','لا تكفي المطابقة النصية؛ يصحح المعلم ملاءمة الأفكار والدليل والترابط.'),
        coalesce((SELECT max(activity_order) FROM public.lesson_activities WHERE lesson_id=target_id),0)+1,5,true,true
      WHERE NOT EXISTS (SELECT 1 FROM public.lesson_activities WHERE lesson_id=target_id AND activity_type='writing' AND content->>'origin'='DADYOOM_BH_TECH_G10_T2_ARAB502_ORIGINAL_20261008');
    END IF;
  END LOOP;
END
$dadyoom$;